class ScopedDisplaySuppressor
{
public:
    ScopedDisplaySuppressor() : previousDisplayCode(UF_DISP_UNSUPPRESS_DISPLAY), active(false)
    {
        if (UF_DISP_ask_display(&previousDisplayCode) == 0 &&
            previousDisplayCode != UF_DISP_SUPPRESS_DISPLAY &&
            UF_DISP_set_display(UF_DISP_SUPPRESS_DISPLAY) == 0)
        {
            active = true;
        }
    }

    ~ScopedDisplaySuppressor()
    {
        Restore(false);
    }

    void Restore(bool regenerate)
    {
        if (!active)
        {
            return;
        }

        UF_DISP_set_display(previousDisplayCode);
        active = false;
        if (regenerate)
        {
            UF_DISP_regenerate_display();
            UF_DISP_refresh();
        }
    }

private:
    int previousDisplayCode;
    bool active;
};

