double Dot3(const double a[3], const double b[3])
{
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}

double Length3(const double a[3])
{
    return std::sqrt(Dot3(a, a));
}

double Distance3(const double a[3], const double b[3])
{
    double delta[3] = { a[0] - b[0], a[1] - b[1], a[2] - b[2] };
    return Length3(delta);
}

void Cross3(const double a[3], const double b[3], double result[3])
{
    result[0] = a[1] * b[2] - a[2] * b[1];
    result[1] = a[2] * b[0] - a[0] * b[2];
    result[2] = a[0] * b[1] - a[1] * b[0];
}

bool Normalize3(double a[3])
{
    const double length = Length3(a);
    if (length < 1.0e-9)
    {
        return false;
    }

    a[0] /= length;
    a[1] /= length;
    a[2] /= length;
    return true;
}

