bool IsPlanarFace(tag_t faceTag)
{
    FaceData data;
    return GetFaceData(faceTag, data) && data.type == UF_MODL_PLANAR_FACE;
}

bool AreCoplanarOrParallelPlanarFaces(tag_t firstFace, tag_t secondFace)
{
    FaceData firstData;
    FaceData secondData;
    if (!GetFaceData(firstFace, firstData) || !GetFaceData(secondFace, secondData) ||
        firstData.type != UF_MODL_PLANAR_FACE || secondData.type != UF_MODL_PLANAR_FACE)
    {
        return false;
    }

    Normalize3(firstData.dir);
    Normalize3(secondData.dir);
    if (std::fabs(Dot3(firstData.dir, secondData.dir)) < kParallelFaceCosTolerance)
    {
        return false;
    }

    const double delta[3] =
    {
        secondData.point[0] - firstData.point[0],
        secondData.point[1] - firstData.point[1],
        secondData.point[2] - firstData.point[2]
    };
    return std::fabs(Dot3(delta, firstData.dir)) < 0.01;
}

bool FacesAreTangentAcrossAnySharedEdge(tag_t firstFace, tag_t secondFace)
{
    std::vector<tag_t> sharedEdges = AskSharedEdges(firstFace, secondFace);
    for (std::size_t index = 0; index < sharedEdges.size(); ++index)
    {
        logical isSmooth = false;
        if (UF_MODL_ask_edge_smoothness(sharedEdges[index], kSmoothEdgeAngleToleranceDegrees, &isSmooth) == 0 && isSmooth)
        {
            return true;
        }
    }
    return false;
}

bool ShouldIncludeInTangentChain(tag_t currentFace, tag_t candidateFace)
{
    if (candidateFace == NULL_TAG || currentFace == candidateFace)
    {
        return false;
    }

    if (AreCoplanarOrParallelPlanarFaces(currentFace, candidateFace))
    {
        return true;
    }

    return FacesAreTangentAcrossAnySharedEdge(currentFace, candidateFace);
}

std::vector<tag_t> CollectTangentFaceChain(tag_t seedFace)
{
    std::vector<tag_t> chain;
    FaceData seedData;
    if (!GetFaceData(seedFace, seedData) ||
        (seedData.type != UF_MODL_PLANAR_FACE &&
         seedData.type != UF_MODL_CYLINDRICAL_FACE &&
         seedData.type != UF_MODL_SWEPT_FACE &&
         seedData.type != UF_MODL_BLENDING_FACE &&
         seedData.type != UF_MODL_PARAMETRIC_FACE))
    {
        return chain;
    }

    std::set<tag_t> visitedFaces;
    std::queue<tag_t> pendingFaces;
    visitedFaces.insert(seedFace);
    pendingFaces.push(seedFace);

    const std::size_t maxChainFaces = 512;
    while (!pendingFaces.empty() && visitedFaces.size() <= maxChainFaces)
    {
        const tag_t currentFace = pendingFaces.front();
        pendingFaces.pop();
        chain.push_back(currentFace);

        const std::vector<tag_t> adjacentFaces = AskAdjacentFaces(currentFace);
        for (std::size_t index = 0; index < adjacentFaces.size(); ++index)
        {
            const tag_t candidateFace = adjacentFaces[index];
            if (visitedFaces.find(candidateFace) != visitedFaces.end())
            {
                continue;
            }

            if (!ShouldIncludeInTangentChain(currentFace, candidateFace))
            {
                continue;
            }

            visitedFaces.insert(candidateFace);
            pendingFaces.push(candidateFace);
        }
    }

    return chain;
}

std::set<tag_t> CollectHoleLoopEdgesForFaceChain(const std::vector<tag_t>& chain)
{
    std::set<tag_t> holeEdges;
    for (std::size_t faceIndex = 0; faceIndex < chain.size(); ++faceIndex)
    {
        uf_loop_p_t loopList = NULL;
        if (UF_MODL_ask_face_loops(chain[faceIndex], &loopList) != 0 || loopList == NULL)
        {
            continue;
        }

        int loopCount = 0;
        if (UF_MODL_ask_loop_list_count(loopList, &loopCount) == 0)
        {
            for (int loopIndex = 0; loopIndex < loopCount; ++loopIndex)
            {
                int loopType = 0;
                uf_list_p_t edgeList = NULL;
                if (UF_MODL_ask_loop_list_item(loopList, loopIndex, &loopType, &edgeList) != 0 ||
                    edgeList == NULL || loopType != 2)
                {
                    continue;
                }

                const std::vector<tag_t> edgeTags = UfListToTags(edgeList);
                holeEdges.insert(edgeTags.begin(), edgeTags.end());
            }
        }

        UF_MODL_delete_loop_list(&loopList);
    }
    return holeEdges;
}

std::vector<tag_t> CollectFaceChainBoundaryEdges(const std::vector<tag_t>& chain)
{
    std::vector<tag_t> boundaryEdges;
    const std::set<tag_t> chainSet(chain.begin(), chain.end());
    const std::set<tag_t> holeEdges = CollectHoleLoopEdgesForFaceChain(chain);
    std::set<tag_t> uniqueEdges;

    for (std::size_t faceIndex = 0; faceIndex < chain.size(); ++faceIndex)
    {
        const std::vector<tag_t> edgeTags = AskFaceEdges(chain[faceIndex]);
        for (std::size_t edgeIndex = 0; edgeIndex < edgeTags.size(); ++edgeIndex)
        {
            const tag_t edgeTag = edgeTags[edgeIndex];
            if (edgeTag == NULL_TAG || uniqueEdges.find(edgeTag) != uniqueEdges.end() ||
                holeEdges.find(edgeTag) != holeEdges.end())
            {
                continue;
            }

            const std::vector<tag_t> adjacentFaces = AskEdgeFaces(edgeTag);
            int chainFaceCount = 0;
            for (std::size_t adjacentIndex = 0; adjacentIndex < adjacentFaces.size(); ++adjacentIndex)
            {
                if (chainSet.find(adjacentFaces[adjacentIndex]) != chainSet.end())
                {
                    ++chainFaceCount;
                }
            }

            if (chainFaceCount == 1)
            {
                uniqueEdges.insert(edgeTag);
                boundaryEdges.push_back(edgeTag);
            }
        }
    }

    return boundaryEdges;
}

std::string PointKey(const double point[3])
{
    long long x = static_cast<long long>(std::llround(point[0] * kPointKeyScale));
    long long y = static_cast<long long>(std::llround(point[1] * kPointKeyScale));
    long long z = static_cast<long long>(std::llround(point[2] * kPointKeyScale));
    return std::to_string(x) + "," + std::to_string(y) + "," + std::to_string(z);
}

bool AskEdgeEndpoints(tag_t edgeTag, double startPoint[3], double endPoint[3])
{
    int vertexCount = 0;
    return edgeTag != NULL_TAG &&
        UF_MODL_ask_edge_verts(edgeTag, startPoint, endPoint, &vertexCount) == 0 &&
        vertexCount >= 2;
}

bool AskFaceEdgePointCenter(tag_t faceTag, double center[3])
{
    const std::vector<tag_t> edgeTags = AskFaceEdges(faceTag);
    if (edgeTags.empty())
    {
        return false;
    }

    center[0] = 0.0;
    center[1] = 0.0;
    center[2] = 0.0;
    int pointCount = 0;
    for (std::size_t index = 0; index < edgeTags.size(); ++index)
    {
        double startPoint[3] = { 0.0, 0.0, 0.0 };
        double endPoint[3] = { 0.0, 0.0, 0.0 };
        if (!AskEdgeEndpoints(edgeTags[index], startPoint, endPoint))
        {
            continue;
        }

        for (int axis = 0; axis < 3; ++axis)
        {
            center[axis] += startPoint[axis] + endPoint[axis];
        }
        pointCount += 2;
    }

    if (pointCount <= 0)
    {
        return false;
    }

    center[0] /= pointCount;
    center[1] /= pointCount;
    center[2] /= pointCount;
    return true;
}

bool AskPlanarFacePlane(tag_t faceTag, double point[3], double normal[3])
{
    FaceData data;
    if (!GetFaceData(faceTag, data) || data.type != UF_MODL_PLANAR_FACE)
    {
        return false;
    }

    point[0] = data.point[0];
    point[1] = data.point[1];
    point[2] = data.point[2];
    normal[0] = data.dir[0];
    normal[1] = data.dir[1];
    normal[2] = data.dir[2];
    if (!Normalize3(normal))
    {
        return false;
    }

    double edgeCenter[3] = { 0.0, 0.0, 0.0 };
    if (AskFaceEdgePointCenter(faceTag, edgeCenter))
    {
        point[0] = edgeCenter[0];
        point[1] = edgeCenter[1];
        point[2] = edgeCenter[2];
    }
    return true;
}

bool AskLongestFaceEdgeDirection(tag_t faceTag, double direction[3], double& length)
{
    direction[0] = 0.0;
    direction[1] = 0.0;
    direction[2] = 0.0;
    length = 0.0;

    const std::vector<tag_t> edgeTags = AskFaceEdges(faceTag);
    for (std::size_t index = 0; index < edgeTags.size(); ++index)
    {
        double startPoint[3] = { 0.0, 0.0, 0.0 };
        double endPoint[3] = { 0.0, 0.0, 0.0 };
        if (!AskEdgeEndpoints(edgeTags[index], startPoint, endPoint))
        {
            continue;
        }

        const double edgeLength = Distance3(startPoint, endPoint);
        if (edgeLength <= length)
        {
            continue;
        }

        length = edgeLength;
        direction[0] = endPoint[0] - startPoint[0];
        direction[1] = endPoint[1] - startPoint[1];
        direction[2] = endPoint[2] - startPoint[2];
    }

    return length > 1.0e-6 && Normalize3(direction);
}

