//------------------------------------------------------------------------------
//Callback Name: apply_cb
//------------------------------------------------------------------------------
int QinLiGuanJian::apply_cb()
{
    int errorCode = 0;
    try
    {
        const int modeAtApply = selectedMode;
        DebugLog("apply begin selectedMode=" + TagToString(static_cast<tag_t>(modeAtApply)));
        if (face_select0 == NULL)
        {
            QinLiGuanJian::theUI->NXMessageBox()->Show("管件斜接处理",
                NXOpen::NXMessageBox::DialogTypeError, "请先选择方管或圆管的侧面。");
            return 1;
        }

        NXOpen::BlockStyler::PropertyList* props = NULL;
        std::vector<NXOpen::TaggedObject*> selectedObjects;
        try
        {
            props = face_select0->GetProperties();
            selectedObjects = props->GetTaggedObjectVector("SelectedObjects");
            delete props;
            props = NULL;
        }
        catch (...)
        {
            if (props != NULL)
            {
                delete props;
            }
            throw;
        }

        if (selectedObjects.empty() || selectedObjects[0] == NULL)
        {
            QinLiGuanJian::theUI->NXMessageBox()->Show("管件斜接处理",
                NXOpen::NXMessageBox::DialogTypeError, "请先选择方管或圆管的侧面。");
            return 1;
        }

        NXOpen::Face* selectedFace = dynamic_cast<NXOpen::Face*>(selectedObjects[0]);
        if (selectedFace == NULL)
        {
            QinLiGuanJian::theUI->NXMessageBox()->Show("管件斜接处理",
                NXOpen::NXMessageBox::DialogTypeError, "当前选择不是有效面。");
            return 1;
        }

        NXOpen::Body* selectedBody = selectedFace->GetBody();
        const tag_t selectedBodyTag = selectedBody != NULL ? selectedBody->Tag() : NULL_TAG;
        DebugLog("selected face=" + TagToString(selectedFace->Tag()) +
            " selected body=" + TagToString(selectedBodyTag));
        ScopedDisplaySuppressor displaySuppressor;
        selectedFace = JoinSelectedBodyFacesOnSameSurface(selectedFace);
        if (selectedFace == NULL)
        {
            QinLiGuanJian::theUI->NXMessageBox()->Show("管件斜接处理",
                NXOpen::NXMessageBox::DialogTypeError, "连结面后未找到有效侧面。");
            return 1;
        }
        DebugLog("selected face after join=" + TagToString(selectedFace->Tag()));

        FaceData selectedFaceData;
        if (!GetFaceData(selectedFace->Tag(), selectedFaceData))
        {
            QinLiGuanJian::theUI->NXMessageBox()->Show("管件斜接处理",
                NXOpen::NXMessageBox::DialogTypeError, "无法识别选择面的类型。");
            return 1;
        }

        int effectiveType = -1;
        if (selectedFaceData.type == UF_MODL_PLANAR_FACE)
        {
            effectiveType = 0;
        }
        else if (selectedFaceData.type == UF_MODL_CYLINDRICAL_FACE)
        {
            effectiveType = 1;
        }
        else
        {
            QinLiGuanJian::theUI->NXMessageBox()->Show("管件斜接处理",
                NXOpen::NXMessageBox::DialogTypeError, "请选择方管平面侧面或圆管圆柱侧面。");
            return 1;
        }

        DebugLog("effective tube type from face=" + TagToString(static_cast<tag_t>(effectiveType)) +
            " selectedMode=" + TagToString(static_cast<tag_t>(modeAtApply)) +
            " faceType=" + TagToString(static_cast<tag_t>(selectedFaceData.type)));

        const std::vector<tag_t> endFaces = FindEndFacesFromSelectedFace(selectedFace);
        DebugLog("endFaces count=" + TagToString(static_cast<tag_t>(endFaces.size())) +
            " tags=" + TagsToString(endFaces));
        if (endFaces.empty())
        {
            QinLiGuanJian::theUI->NXMessageBox()->Show("管件斜接处理",
                NXOpen::NXMessageBox::DialogTypeError, "未找到可抽取的端面。");
            return 1;
        }

        NXOpen::Face* innerFace = effectiveType == 0 ?
            FindSquareTubeInnerFace(selectedFace) :
            FindRoundTubeInnerFace(selectedFace);
        DebugLog("innerFace=" + TagToString(innerFace != NULL ? innerFace->Tag() : NULL_TAG));
        if (innerFace == NULL)
        {
            QinLiGuanJian::theUI->NXMessageBox()->Show("管件斜接处理",
                NXOpen::NXMessageBox::DialogTypeError,
                effectiveType == 0 ? "未找到方管内侧面，无法执行清理实用工具。" :
                "未找到圆管同心内侧面，无法执行清理实用工具。");
            return 1;
        }

        const std::vector<tag_t> extractedSheetBodies = ExtractEndFacesAsFaceChain(endFaces);
        DebugLog("extractedSheetBodies count=" +
            TagToString(static_cast<tag_t>(extractedSheetBodies.size())) +
            " tags=" + TagsToString(extractedSheetBodies));
        const tag_t cleanedBody = CleanUpSquareTubeWithInnerFace(innerFace);
        DebugLog("first cleanedBody=" + TagToString(cleanedBody));
        const tag_t trimmedBody = TrimBodyWithExtractedSheets(cleanedBody, extractedSheetBodies);
        DebugLog("trimmedBody=" + TagToString(trimmedBody));
        NXOpen::Face* outerFace = FindMatchingOuterFaceOnBody(trimmedBody, selectedFace);
        DebugLog("outerFace=" + TagToString(outerFace != NULL ? outerFace->Tag() : NULL_TAG));
        if (outerFace == NULL)
        {
            QinLiGuanJian::theUI->NXMessageBox()->Show("管件斜接处理",
                NXOpen::NXMessageBox::DialogTypeError, "未找到修剪后管件的外侧面，无法执行第二次清理。");
            return 1;
        }
        tag_t finalCleanedBody = CleanUpSquareTubeWithInnerFace(outerFace);
        DebugLog("finalCleanedBody=" + TagToString(finalCleanedBody));
        std::vector<tag_t> intermediateBodies = extractedSheetBodies;
        intermediateBodies.push_back(cleanedBody);
        intermediateBodies.push_back(trimmedBody);
        if (modeAtApply == 1 && effectiveType == 0)
        {
            DebugLog("sharp corner mode start finalBody=" + TagToString(finalCleanedBody));
            finalCleanedBody = ApplySharpCornerBoundingSubtract(
                finalCleanedBody,
                selectedFace,
                endFaces,
                intermediateBodies);
            DebugLog("sharp corner mode end finalBody=" + TagToString(finalCleanedBody));
        }
        DebugLog("delete intermediates original=" + TagToString(selectedBodyTag) +
            " final=" + TagToString(finalCleanedBody) +
            " bodies=" + TagsToString(intermediateBodies));
        DeleteIntermediateBodies(selectedBodyTag, finalCleanedBody, intermediateBodies);
        displaySuppressor.Restore(true);
        RefreshFinalDisplay(finalCleanedBody);
        DebugLog("apply ok");
    }
    catch(NXOpen::NXException& ex)
    {
        errorCode = 1;
        DebugLogNxException("apply", ex);
        QinLiGuanJian::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        errorCode = 1;
        DebugLog(std::string("apply std exception: ") + ex.what());
        QinLiGuanJian::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return errorCode;
}

