void QinLiGuanJian::ClearHighlightedFaces()
{
    for (std::size_t index = 0; index < highlightedFaceTags.size(); ++index)
    {
        NXOpen::DisplayableObject* displayObject =
            dynamic_cast<NXOpen::DisplayableObject*>(NXOpen::NXObjectManager::Get(highlightedFaceTags[index]));
        if (displayObject != NULL)
        {
            displayObject->Unhighlight();
        }
    }
    highlightedFaceTags.clear();
}

void QinLiGuanJian::HighlightFaces(const std::vector<tag_t>& faceTags)
{
    ClearHighlightedFaces();

    std::set<tag_t> uniqueFaces;
    for (std::size_t index = 0; index < faceTags.size(); ++index)
    {
        const tag_t faceTag = faceTags[index];
        if (faceTag == NULL_TAG || !uniqueFaces.insert(faceTag).second)
        {
            continue;
        }

        NXOpen::DisplayableObject* displayObject =
            dynamic_cast<NXOpen::DisplayableObject*>(NXOpen::NXObjectManager::Get(faceTag));
        if (displayObject == NULL)
        {
            continue;
        }

        displayObject->Highlight();
        highlightedFaceTags.push_back(faceTag);
    }
}

void QinLiGuanJian::RefreshFinalDisplay(tag_t finalBodyTag)
{
    try
    {
        if (finalBodyTag != NULL_TAG)
        {
            NXOpen::DisplayableObject* displayObject =
                dynamic_cast<NXOpen::DisplayableObject*>(NXOpen::NXObjectManager::Get(finalBodyTag));
            if (displayObject != NULL)
            {
                displayObject->Unblank();
                displayObject->RedisplayObject();
            }
        }

        UF_DISP_regenerate_display();
        if (QinLiGuanJian::theSession != NULL &&
            QinLiGuanJian::theSession->DisplayManager() != NULL)
        {
            QinLiGuanJian::theSession->DisplayManager()->MakeUpToDate();
        }
        UF_DISP_refresh();
        DebugLog("RefreshFinalDisplay done finalBody=" + TagToString(finalBodyTag));
    }
    catch (NXOpen::NXException& ex)
    {
        DebugLogNxException("RefreshFinalDisplay finalBody=" + TagToString(finalBodyTag), ex);
    }
    catch (...)
    {
        DebugLog("RefreshFinalDisplay unknown exception finalBody=" + TagToString(finalBodyTag));
    }
}

std::vector<tag_t> QinLiGuanJian::FindEndFacesFromSelectedFace(NXOpen::Face* selectedFace)
{
    std::vector<tag_t> endFaces;
    if (selectedFace == NULL)
    {
        return endFaces;
    }

    FaceData selectedData;
    if (!GetFaceData(selectedFace->Tag(), selectedData))
    {
        return endFaces;
    }

    if (selectedData.type == UF_MODL_CYLINDRICAL_FACE)
    {
        endFaces = CollectCylinderEndFacesFromSideFace(selectedFace->Tag());
        DebugLog("round tube cylinder end faces count=" +
            TagToString(static_cast<tag_t>(endFaces.size())) +
            " tags=" + TagsToString(endFaces));
        if (!endFaces.empty())
        {
            return endFaces;
        }
    }

    if (selectedData.type != UF_MODL_PLANAR_FACE)
    {
        DebugLog("unsupported selected face type for end faces=" +
            TagToString(static_cast<tag_t>(selectedData.type)));
        return endFaces;
    }

    const std::vector<tag_t> faceChain = CollectTangentFaceChain(selectedFace->Tag());
    const std::vector<tag_t> boundaryEdges = CollectFaceChainBoundaryEdges(faceChain);
    const std::set<tag_t> chainFaces(faceChain.begin(), faceChain.end());
    std::set<tag_t> endFaceSet;
    for (std::size_t edgeIndex = 0; edgeIndex < boundaryEdges.size(); ++edgeIndex)
    {
        const std::vector<tag_t> adjacentFaces = AskEdgeFaces(boundaryEdges[edgeIndex]);
        for (std::size_t faceIndex = 0; faceIndex < adjacentFaces.size(); ++faceIndex)
        {
            const tag_t adjacentFace = adjacentFaces[faceIndex];
            if (adjacentFace != NULL_TAG && chainFaces.find(adjacentFace) == chainFaces.end())
            {
                endFaceSet.insert(adjacentFace);
            }
        }
    }

    endFaces.assign(endFaceSet.begin(), endFaceSet.end());
    return endFaces;
}

NXOpen::Face* QinLiGuanJian::FindSquareTubeInnerFace(NXOpen::Face* selectedFace)
{
    if (selectedFace == NULL)
    {
        return NULL;
    }

    FaceData selectedData;
    if (!GetFaceData(selectedFace->Tag(), selectedData) || selectedData.type != UF_MODL_PLANAR_FACE)
    {
        return NULL;
    }

    tag_t bodyTag = NULL_TAG;
    if (UF_MODL_ask_face_body(selectedFace->Tag(), &bodyTag) != 0 || bodyTag == NULL_TAG)
    {
        return NULL;
    }

    double selectedNormal[3] = { selectedData.dir[0], selectedData.dir[1], selectedData.dir[2] };
    if (!Normalize3(selectedNormal))
    {
        return NULL;
    }

    const double selectedOffset = PlaneOffsetAlongNormal(selectedData, selectedNormal);
    const std::vector<tag_t> bodyFaces = AskBodyFaces(bodyTag);
    tag_t bestFaceTag = NULL_TAG;
    double bestDistance = std::numeric_limits<double>::max();

    for (std::size_t index = 0; index < bodyFaces.size(); ++index)
    {
        const tag_t candidateTag = bodyFaces[index];
        if (candidateTag == NULL_TAG || candidateTag == selectedFace->Tag())
        {
            continue;
        }

        FaceData candidateData;
        if (!GetFaceData(candidateTag, candidateData) ||
            !IsOppositeParallelPlanarFace(selectedData, candidateData))
        {
            continue;
        }

        const double candidateOffset = PlaneOffsetAlongNormal(candidateData, selectedNormal);
        const double distance = std::fabs(candidateOffset - selectedOffset);
        if (distance > 1.0e-6 && distance < bestDistance)
        {
            bestDistance = distance;
            bestFaceTag = candidateTag;
        }
    }

    return bestFaceTag != NULL_TAG ?
        dynamic_cast<NXOpen::Face*>(NXOpen::NXObjectManager::Get(bestFaceTag)) : NULL;
}

NXOpen::Face* QinLiGuanJian::FindRoundTubeInnerFace(NXOpen::Face* selectedFace)
{
    if (selectedFace == NULL)
    {
        return NULL;
    }

    FaceData selectedData;
    if (!GetFaceData(selectedFace->Tag(), selectedData) ||
        selectedData.type != UF_MODL_CYLINDRICAL_FACE)
    {
        return NULL;
    }

    tag_t bodyTag = NULL_TAG;
    if (UF_MODL_ask_face_body(selectedFace->Tag(), &bodyTag) != 0 || bodyTag == NULL_TAG)
    {
        return NULL;
    }

    double selectedAxis[3] = { selectedData.dir[0], selectedData.dir[1], selectedData.dir[2] };
    if (!Normalize3(selectedAxis))
    {
        return NULL;
    }

    const std::vector<tag_t> bodyFaces = AskBodyFaces(bodyTag);
    tag_t bestFaceTag = NULL_TAG;
    double bestRadius = std::numeric_limits<double>::max();
    for (std::size_t index = 0; index < bodyFaces.size(); ++index)
    {
        const tag_t candidateTag = bodyFaces[index];
        if (candidateTag == NULL_TAG || candidateTag == selectedFace->Tag())
        {
            continue;
        }

        FaceData candidateData;
        if (!GetFaceData(candidateTag, candidateData) ||
            candidateData.type != UF_MODL_CYLINDRICAL_FACE)
        {
            continue;
        }

        double candidateAxis[3] = { candidateData.dir[0], candidateData.dir[1], candidateData.dir[2] };
        if (!Normalize3(candidateAxis) ||
            std::fabs(Dot3(selectedAxis, candidateAxis)) < kParallelFaceCosTolerance)
        {
            continue;
        }

        double centerDelta[3] =
        {
            candidateData.point[0] - selectedData.point[0],
            candidateData.point[1] - selectedData.point[1],
            candidateData.point[2] - selectedData.point[2]
        };
        const double axialDistance = Dot3(centerDelta, selectedAxis);
        double radialDelta[3] =
        {
            centerDelta[0] - axialDistance * selectedAxis[0],
            centerDelta[1] - axialDistance * selectedAxis[1],
            centerDelta[2] - axialDistance * selectedAxis[2]
        };
        if (Length3(radialDelta) > 0.01 ||
            candidateData.radius >= selectedData.radius - 1.0e-6)
        {
            continue;
        }

        if (candidateData.radius < bestRadius)
        {
            bestRadius = candidateData.radius;
            bestFaceTag = candidateTag;
        }
    }

    return bestFaceTag != NULL_TAG ?
        dynamic_cast<NXOpen::Face*>(NXOpen::NXObjectManager::Get(bestFaceTag)) : NULL;
}

NXOpen::Face* QinLiGuanJian::FindMatchingOuterFaceOnBody(tag_t bodyTag, NXOpen::Face* referenceFace)
{
    if (bodyTag == NULL_TAG || referenceFace == NULL)
    {
        return NULL;
    }

    FaceData referenceData;
    if (!GetFaceData(referenceFace->Tag(), referenceData))
    {
        return NULL;
    }

    if (referenceData.type == UF_MODL_CYLINDRICAL_FACE)
    {
        double referenceAxis[3] =
        {
            referenceData.dir[0],
            referenceData.dir[1],
            referenceData.dir[2]
        };
        if (!Normalize3(referenceAxis))
        {
            return NULL;
        }

        const std::vector<tag_t> bodyFaces = AskBodyFaces(bodyTag);
        tag_t bestFaceTag = NULL_TAG;
        double bestScore = std::numeric_limits<double>::max();
        for (std::size_t index = 0; index < bodyFaces.size(); ++index)
        {
            FaceData candidateData;
            if (!GetFaceData(bodyFaces[index], candidateData) ||
                candidateData.type != UF_MODL_CYLINDRICAL_FACE)
            {
                continue;
            }

            double candidateAxis[3] =
            {
                candidateData.dir[0],
                candidateData.dir[1],
                candidateData.dir[2]
            };
            if (!Normalize3(candidateAxis) ||
                std::fabs(Dot3(referenceAxis, candidateAxis)) < kParallelFaceCosTolerance)
            {
                continue;
            }

            double centerDelta[3] =
            {
                candidateData.point[0] - referenceData.point[0],
                candidateData.point[1] - referenceData.point[1],
                candidateData.point[2] - referenceData.point[2]
            };
            const double axialDistance = Dot3(centerDelta, referenceAxis);
            double radialDelta[3] =
            {
                centerDelta[0] - axialDistance * referenceAxis[0],
                centerDelta[1] - axialDistance * referenceAxis[1],
                centerDelta[2] - axialDistance * referenceAxis[2]
            };
            const double score = Length3(radialDelta) + std::fabs(candidateData.radius - referenceData.radius);
            if (score < bestScore)
            {
                bestScore = score;
                bestFaceTag = bodyFaces[index];
            }
        }

        return bestFaceTag != NULL_TAG ?
            dynamic_cast<NXOpen::Face*>(NXOpen::NXObjectManager::Get(bestFaceTag)) : NULL;
    }

    if (referenceData.type != UF_MODL_PLANAR_FACE)
    {
        return NULL;
    }

    double referenceNormal[3] =
    {
        referenceData.dir[0],
        referenceData.dir[1],
        referenceData.dir[2]
    };
    if (!Normalize3(referenceNormal))
    {
        return NULL;
    }

    const double referenceOffset = PlaneOffsetAlongNormal(referenceData, referenceNormal);
    const std::vector<tag_t> bodyFaces = AskBodyFaces(bodyTag);
    tag_t bestFaceTag = NULL_TAG;
    double bestOffsetDifference = std::numeric_limits<double>::max();
    double bestScore = -1.0;

    for (std::size_t index = 0; index < bodyFaces.size(); ++index)
    {
        FaceData candidateData;
        if (!GetFaceData(bodyFaces[index], candidateData) ||
            candidateData.type != UF_MODL_PLANAR_FACE)
        {
            continue;
        }

        double candidateNormal[3] =
        {
            candidateData.dir[0],
            candidateData.dir[1],
            candidateData.dir[2]
        };
        if (!Normalize3(candidateNormal) ||
            Dot3(referenceNormal, candidateNormal) < kParallelFaceCosTolerance)
        {
            continue;
        }

        const double offsetDifference =
            std::fabs(PlaneOffsetAlongNormal(candidateData, referenceNormal) - referenceOffset);
        if (offsetDifference > 1.0e-3)
        {
            continue;
        }

        const double dx = std::max(0.0, candidateData.box[3] - candidateData.box[0]);
        const double dy = std::max(0.0, candidateData.box[4] - candidateData.box[1]);
        const double dz = std::max(0.0, candidateData.box[5] - candidateData.box[2]);
        const double score = dx * dx + dy * dy + dz * dz;
        if (offsetDifference < bestOffsetDifference - 1.0e-6 ||
            (std::fabs(offsetDifference - bestOffsetDifference) <= 1.0e-6 && score > bestScore))
        {
            bestOffsetDifference = offsetDifference;
            bestScore = score;
            bestFaceTag = bodyFaces[index];
        }
    }

    return bestFaceTag != NULL_TAG ?
        dynamic_cast<NXOpen::Face*>(NXOpen::NXObjectManager::Get(bestFaceTag)) : NULL;
}

NXOpen::Face* QinLiGuanJian::JoinSelectedBodyFacesOnSameSurface(NXOpen::Face* selectedFace)
{
    if (selectedFace == NULL)
    {
        return NULL;
    }

    NXOpen::Body* selectedBody = selectedFace->GetBody();
    const tag_t bodyTag = selectedBody != NULL ? selectedBody->Tag() : NULL_TAG;
    const tag_t originalFaceTag = selectedFace->Tag();
    if (bodyTag == NULL_TAG)
    {
        return selectedFace;
    }

    FaceData referenceData;
    if (!GetFaceData(originalFaceTag, referenceData))
    {
        DebugLog("join same surface skipped: cannot read selected face data face=" +
            TagToString(originalFaceTag));
        return selectedFace;
    }

    tag_t faceTags[2] = { NULL_TAG, NULL_TAG };
    tag_t resultFeatureTag = NULL_TAG;
    const int errorCode = UF_MODL_edit_face_join(1, bodyTag, faceTags, &resultFeatureTag);
    if (errorCode != 0)
    {
        DebugLog("join same surface failed body=" + TagToString(bodyTag) +
            " face=" + TagToString(originalFaceTag) +
            " error=" + TagToString(static_cast<tag_t>(errorCode)));
        return selectedFace;
    }

    DebugLog("join same surface ok body=" + TagToString(bodyTag) +
        " feature=" + TagToString(resultFeatureTag));

    const std::vector<tag_t> bodyFaces = AskBodyFaces(bodyTag);
    tag_t bestFaceTag = NULL_TAG;
    double bestScore = std::numeric_limits<double>::max();

    double referenceDir[3] = { referenceData.dir[0], referenceData.dir[1], referenceData.dir[2] };
    Normalize3(referenceDir);
    for (std::size_t index = 0; index < bodyFaces.size(); ++index)
    {
        FaceData candidateData;
        if (!GetFaceData(bodyFaces[index], candidateData) ||
            candidateData.type != referenceData.type)
        {
            continue;
        }

        double candidateDir[3] = { candidateData.dir[0], candidateData.dir[1], candidateData.dir[2] };
        Normalize3(candidateDir);
        const double directionScore = std::fabs(Dot3(referenceDir, candidateDir));
        if (directionScore < kParallelFaceCosTolerance)
        {
            continue;
        }

        double score = Distance3(referenceData.point, candidateData.point);
        if (referenceData.type == UF_MODL_PLANAR_FACE)
        {
            score = std::fabs(PlaneOffsetAlongNormal(candidateData, referenceDir) -
                PlaneOffsetAlongNormal(referenceData, referenceDir));
        }
        else if (referenceData.type == UF_MODL_CYLINDRICAL_FACE)
        {
            score += std::fabs(candidateData.radius - referenceData.radius);
        }

        if (score < bestScore)
        {
            bestScore = score;
            bestFaceTag = bodyFaces[index];
        }
    }

    if (bestFaceTag == NULL_TAG)
    {
        DebugLog("join same surface cannot rematch selected face, use original face=" +
            TagToString(originalFaceTag));
        return selectedFace;
    }

    DebugLog("join same surface rematch selected face old=" + TagToString(originalFaceTag) +
        " new=" + TagToString(bestFaceTag));
    NXOpen::Face* rematchedFace =
        dynamic_cast<NXOpen::Face*>(NXOpen::NXObjectManager::Get(bestFaceTag));
    return rematchedFace != NULL ? rematchedFace : selectedFace;
}

tag_t QinLiGuanJian::CleanUpSquareTubeWithInnerFace(NXOpen::Face* innerFace)
{
    if (innerFace == NULL)
    {
        throw std::runtime_error("未找到方管内侧面，无法执行清理实用工具。");
    }

    NXOpen::Part* workPart =
        QinLiGuanJian::theSession != NULL && QinLiGuanJian::theSession->Parts() != NULL ?
        QinLiGuanJian::theSession->Parts()->Work() : NULL;
    if (workPart == NULL)
    {
        throw std::runtime_error("未找到工作部件。");
    }

    NXOpen::Features::SheetMetal::CleanUpUtilityBuilder* builder =
        workPart->Features()->SheetmetalManager()->CreateCleanUpUtilityBuilder();
    if (builder == NULL)
    {
        throw std::runtime_error("无法创建清理实用工具。");
    }

    try
    {
        builder->SetApplicationContext(NXOpen::Features::SheetMetal::ApplicationContextNxSheetMetal);
        builder->SetInferThickness(true);
        double cleanupThickness = 0.0;
        if (!CalculateCleanupThickness(innerFace, cleanupThickness))
        {
            throw std::runtime_error("无法计算清理工具厚度。");
        }
        builder->ThicknessValue()->SetFormula(DoubleToString(cleanupThickness));
        builder->SliverTolerance()->SetFormula("0.01");
        builder->ThicknessTolerance()->SetFormula("0");
        builder->SetHideOriginal(true);

        NXOpen::SelectionIntentRuleOptions* ruleOptions = workPart->ScRuleFactory()->CreateRuleOptions();
        ruleOptions->SetSelectedFromInactive(false);
        std::vector<NXOpen::Face*> faces(1, innerFace);
        NXOpen::FaceDumbRule* faceRule = workPart->ScRuleFactory()->CreateRuleFaceDumb(faces, ruleOptions);
        delete ruleOptions;
        ruleOptions = NULL;

        std::vector<NXOpen::SelectionIntentRule*> rules(1, faceRule);
        builder->SelectBaseFace()->ReplaceRules(rules, false);

        NXOpen::Features::Feature* feature = builder->CommitFeature();
        const tag_t bodyTag = AskFirstBodyFromFeature(feature);
        if (feature == NULL || bodyTag == NULL_TAG)
        {
            throw std::runtime_error("清理实用工具创建失败。");
        }

        builder->Destroy();
        return bodyTag;
    }
    catch (...)
    {
        builder->Destroy();
        throw;
    }
}

tag_t QinLiGuanJian::TrimBodyWithExtractedSheets(tag_t targetBodyTag, const std::vector<tag_t>& toolBodyTags)
{
    if (targetBodyTag == NULL_TAG || toolBodyTags.empty())
    {
        return targetBodyTag;
    }

    NXOpen::Part* workPart =
        QinLiGuanJian::theSession != NULL && QinLiGuanJian::theSession->Parts() != NULL ?
        QinLiGuanJian::theSession->Parts()->Work() : NULL;
    if (workPart == NULL)
    {
        throw std::runtime_error("未找到工作部件。");
    }

    NXOpen::Body* targetBody = dynamic_cast<NXOpen::Body*>(NXOpen::NXObjectManager::Get(targetBodyTag));
    if (targetBody == NULL)
    {
        throw std::runtime_error("未找到清理后的目标体。");
    }

    for (std::size_t index = 0; index < toolBodyTags.size(); ++index)
    {
        const tag_t toolBodyTag = toolBodyTags[index];
        if (toolBodyTag == NULL_TAG)
        {
            continue;
        }

        NXOpen::Body* toolBody = dynamic_cast<NXOpen::Body*>(NXOpen::NXObjectManager::Get(toolBodyTag));
        if (toolBody == NULL)
        {
            continue;
        }

        NXOpen::Features::TrimBody2Builder* builder =
            workPart->Features()->CreateTrimBody2Builder(NULL);
        if (builder == NULL)
        {
            throw std::runtime_error("无法创建修剪体构建器。");
        }

        try
        {
            NXOpen::SelectionIntentRuleOptions* targetRuleOptions =
                workPart->ScRuleFactory()->CreateRuleOptions();
            targetRuleOptions->SetSelectedFromInactive(false);
            std::vector<NXOpen::Body*> targets(1, targetBody);
            NXOpen::BodyDumbRule* targetRule =
                workPart->ScRuleFactory()->CreateRuleBodyDumb(targets, true, targetRuleOptions);
            delete targetRuleOptions;
            targetRuleOptions = NULL;

            NXOpen::ScCollector* targetCollector = workPart->ScCollectors()->CreateCollector();
            std::vector<NXOpen::SelectionIntentRule*> targetRules(1, targetRule);
            targetCollector->ReplaceRules(targetRules, false);
            builder->SetTargetBodyCollector(targetCollector);

            NXOpen::SelectionIntentRuleOptions* toolRuleOptions =
                workPart->ScRuleFactory()->CreateRuleOptions();
            toolRuleOptions->SetSelectedFromInactive(false);
            NXOpen::FaceBodyRule* toolRule =
                workPart->ScRuleFactory()->CreateRuleFaceBody(toolBody, toolRuleOptions);
            delete toolRuleOptions;
            toolRuleOptions = NULL;

            NXOpen::GeometricUtilities::BooleanToolBuilder* booleanTool = builder->BooleanTool();
            booleanTool->SetToolOption(
                NXOpen::GeometricUtilities::BooleanToolBuilder::BooleanToolTypeFaceOrPlane);
            std::vector<NXOpen::SelectionIntentRule*> toolRules(1, toolRule);
            NXOpen::ScCollector* faceCollector =
                booleanTool->FacePlaneTool()->ToolFaces()->FaceCollector();
            faceCollector->ReplaceRules(toolRules, false);
            booleanTool->FacePlaneTool()->ToolFaces()->SetReverseNormalFlag(false);
            builder->SetTolerance(0.01);
            booleanTool->ExtrudeRevolveTool()->ToolSection()->SetDistanceTolerance(0.01);
            booleanTool->ExtrudeRevolveTool()->ToolSection()->SetChainingTolerance(0.0095);

            NXOpen::Features::Feature* feature = builder->CommitFeature();
            const tag_t trimmedBodyTag = AskFirstBodyFromFeature(feature);
            if (feature == NULL || trimmedBodyTag == NULL_TAG)
            {
                throw std::runtime_error("抽取面剪切清理体失败。");
            }

            targetBodyTag = trimmedBodyTag;
            targetBody = dynamic_cast<NXOpen::Body*>(NXOpen::NXObjectManager::Get(targetBodyTag));
            if (targetBody == NULL)
            {
                throw std::runtime_error("无法取得剪切后的目标体。");
            }
            RestoreBodyDisplay(toolBodyTag, "trim success keep tool body");
        }
        catch (NXOpen::NXException& ex)
        {
            builder->Destroy();
            const std::string message = ex.what() != NULL ? ex.what() : "";
            if (ex.ErrorCode() == 670028 ||
                ex.ErrorCode() == 670362 ||
                message.find("Tool body completely outside target body") != std::string::npos)
            {
                DebugLog("TrimBodyWithExtractedSheets skip failed tool body=" +
                    TagToString(toolBodyTag) +
                    " code=" + TagToString(static_cast<tag_t>(ex.ErrorCode())) +
                    " message=" + message);
                RestoreBodyDisplay(toolBodyTag, "trim failed skipped");
                continue;
            }
            throw;
        }
        catch (...)
        {
            builder->Destroy();
            throw;
        }

        builder->Destroy();
    }

    return targetBodyTag;
}

tag_t QinLiGuanJian::ApplySharpCornerBoundingSubtract(
    tag_t finalBodyTag,
    NXOpen::Face* squareTubeFace,
    const std::vector<tag_t>& originalEndFaces,
    std::vector<tag_t>& intermediateBodyTags)
{
    if (finalBodyTag == NULL_TAG || squareTubeFace == NULL || originalEndFaces.empty())
    {
        DebugLog("sharp corner skipped: invalid input finalBody=" + TagToString(finalBodyTag) +
            " squareFace=" + TagToString(squareTubeFace != NULL ? squareTubeFace->Tag() : NULL_TAG) +
            " originalEndFaces=" + TagsToString(originalEndFaces));
        return finalBodyTag;
    }

    NXOpen::Part* workPart =
        QinLiGuanJian::theSession != NULL && QinLiGuanJian::theSession->Parts() != NULL ?
        QinLiGuanJian::theSession->Parts()->Work() : NULL;
    if (workPart == NULL || workPart->Features() == NULL ||
        workPart->Features()->ToolingFeatureCollection() == NULL)
    {
        DebugLog("sharp corner skipped: no work part/tooling feature collection");
        return finalBodyTag;
    }

    double referencePoint[3] = { 0.0, 0.0, 0.0 };
    double referenceNormal[3] = { 0.0, 0.0, 0.0 };
    if (!AskPlanarFacePlane(squareTubeFace->Tag(), referencePoint, referenceNormal))
    {
        DebugLog("sharp corner skipped: selected square face is not usable planar face=" +
            TagToString(squareTubeFace->Tag()));
        return finalBodyTag;
    }

    double longDirection[3] = { 0.0, 0.0, 0.0 };
    double longLength = 0.0;
    if (!AskLongestFaceEdgeDirection(squareTubeFace->Tag(), longDirection, longLength))
    {
        DebugLog("sharp corner skipped: cannot find longest edge direction on square face=" +
            TagToString(squareTubeFace->Tag()));
        return finalBodyTag;
    }

    const double projection = Dot3(longDirection, referenceNormal);
    longDirection[0] -= projection * referenceNormal[0];
    longDirection[1] -= projection * referenceNormal[1];
    longDirection[2] -= projection * referenceNormal[2];
    if (!Normalize3(longDirection))
    {
        DebugLog("sharp corner skipped: projected longest edge direction invalid");
        return finalBodyTag;
    }

    double yDirection[3] = { 0.0, 0.0, 0.0 };
    Cross3(referenceNormal, longDirection, yDirection);
    if (!Normalize3(yDirection))
    {
        DebugLog("sharp corner skipped: cannot build tooling box y direction");
        return finalBodyTag;
    }

    NXOpen::Matrix3x3 boxMatrix = {};
    boxMatrix.Xx = longDirection[0];
    boxMatrix.Xy = longDirection[1];
    boxMatrix.Xz = longDirection[2];
    boxMatrix.Yx = yDirection[0];
    boxMatrix.Yy = yDirection[1];
    boxMatrix.Yz = yDirection[2];
    boxMatrix.Zx = referenceNormal[0];
    boxMatrix.Zy = referenceNormal[1];
    boxMatrix.Zz = referenceNormal[2];
    NXOpen::Point3d boxOrigin(referencePoint[0], referencePoint[1], referencePoint[2]);

    std::set<tag_t> finalEndFaceSet;
    const std::vector<tag_t> finalBodyFaces = AskBodyFaces(finalBodyTag);
    for (std::size_t sourceIndex = 0; sourceIndex < originalEndFaces.size(); ++sourceIndex)
    {
        double endPoint[3] = { 0.0, 0.0, 0.0 };
        double endNormal[3] = { 0.0, 0.0, 0.0 };
        if (!AskPlanarFacePlane(originalEndFaces[sourceIndex], endPoint, endNormal))
        {
            DebugLog("sharp corner original end face skipped: non-planar face=" +
                TagToString(originalEndFaces[sourceIndex]));
            continue;
        }

        const double endOffset = Dot3(endPoint, endNormal);
        tag_t bestFace = NULL_TAG;
        double bestOffset = std::numeric_limits<double>::max();
        double bestScore = -1.0;
        for (std::size_t faceIndex = 0; faceIndex < finalBodyFaces.size(); ++faceIndex)
        {
            FaceData candidateData;
            if (!GetFaceData(finalBodyFaces[faceIndex], candidateData) ||
                candidateData.type != UF_MODL_PLANAR_FACE)
            {
                continue;
            }

            double candidateNormal[3] =
            {
                candidateData.dir[0],
                candidateData.dir[1],
                candidateData.dir[2]
            };
            if (!Normalize3(candidateNormal) ||
                std::fabs(Dot3(candidateNormal, endNormal)) < kParallelFaceCosTolerance)
            {
                continue;
            }

            const double offsetDifference =
                std::fabs(Dot3(candidateData.point, endNormal) - endOffset);
            if (offsetDifference > 0.05)
            {
                continue;
            }

            const double dx = std::max(0.0, candidateData.box[3] - candidateData.box[0]);
            const double dy = std::max(0.0, candidateData.box[4] - candidateData.box[1]);
            const double dz = std::max(0.0, candidateData.box[5] - candidateData.box[2]);
            const double score = dx * dx + dy * dy + dz * dz;
            if (offsetDifference < bestOffset - 1.0e-6 ||
                (std::fabs(offsetDifference - bestOffset) <= 1.0e-6 && score > bestScore))
            {
                bestOffset = offsetDifference;
                bestScore = score;
                bestFace = finalBodyFaces[faceIndex];
            }
        }

        if (bestFace != NULL_TAG)
        {
            finalEndFaceSet.insert(bestFace);
            DebugLog("sharp corner rematch end face source=" + TagToString(originalEndFaces[sourceIndex]) +
                " final=" + TagToString(bestFace) +
                " offsetDiff=" + DoubleToString(bestOffset));
        }
        else
        {
            DebugLog("sharp corner rematch end face failed source=" +
                TagToString(originalEndFaces[sourceIndex]));
        }
    }

    std::set<tag_t> bSurfaceSet;
    for (std::set<tag_t>::const_iterator endIt = finalEndFaceSet.begin();
        endIt != finalEndFaceSet.end();
        ++endIt)
    {
        std::set<tag_t> endBSurfaces;
        const std::vector<tag_t> adjacentFaces = AskAdjacentFaces(*endIt);
        for (std::size_t index = 0; index < adjacentFaces.size(); ++index)
        {
            const tag_t adjacentFace = adjacentFaces[index];
            if (adjacentFace != NULL_TAG && IsBSurfaceFace(adjacentFace))
            {
                bSurfaceSet.insert(adjacentFace);
                endBSurfaces.insert(adjacentFace);
            }
        }

        DebugLog("sharp corner end face B-surfaces endFace=" + TagToString(*endIt) +
            " count=" + TagToString(static_cast<tag_t>(endBSurfaces.size())) +
            " tags=" + TagsToString(std::vector<tag_t>(
                endBSurfaces.begin(), endBSurfaces.end())));
    }

    if (bSurfaceSet.empty())
    {
        DebugLog("sharp corner skipped: no B-surfaces found on final end faces");
        return finalBodyTag;
    }

    std::vector<tag_t> toolBodyTags;
    std::vector<tag_t> toolFeatureTags;
    const std::string offsetText = "0";
    for (std::set<tag_t>::const_iterator bIt = bSurfaceSet.begin(); bIt != bSurfaceSet.end(); ++bIt)
    {
        NXOpen::Face* bFace =
            dynamic_cast<NXOpen::Face*>(NXOpen::NXObjectManager::Get(*bIt));
        if (bFace == NULL)
        {
            DebugLog("sharp corner tooling box skipped invalid B-surface=" + TagToString(*bIt));
            continue;
        }

        NXOpen::Features::ToolingBoxBuilder* builder =
            workPart->Features()->ToolingFeatureCollection()->CreateToolingBoxBuilder(NULL);
        if (builder == NULL)
        {
            DebugLog("sharp corner tooling box skipped: builder null B-surface=" + TagToString(*bIt));
            continue;
        }

        tag_t boxFeatureTag = NULL_TAG;
        tag_t toolBodyTag = NULL_TAG;
        try
        {
            builder->SetReferenceCsysType(
                NXOpen::Features::ToolingBoxBuilder::RefCsysTypeAbsoluteinDisplayedPart);
            builder->SetType(NXOpen::Features::ToolingBoxBuilder::TypesBoundedBlock);
            builder->SetShowDimension(false);
            builder->SetSingleOffset(false);
            builder->OffsetPositiveX()->SetFormula(offsetText.c_str());
            builder->OffsetNegativeX()->SetFormula(offsetText.c_str());
            builder->OffsetPositiveY()->SetFormula(offsetText.c_str());
            builder->OffsetNegativeY()->SetFormula(offsetText.c_str());
            builder->OffsetPositiveZ()->SetFormula(offsetText.c_str());
            builder->OffsetNegativeZ()->SetFormula(offsetText.c_str());
            builder->SetBoxMatrixAndPosition(boxMatrix, boxOrigin);

            NXOpen::SelectionIntentRuleOptions* ruleOptions =
                workPart->ScRuleFactory()->CreateRuleOptions();
            ruleOptions->SetSelectedFromInactive(false);
            std::vector<NXOpen::Face*> faces(1, bFace);
            NXOpen::FaceDumbRule* faceRule =
                workPart->ScRuleFactory()->CreateRuleFaceDumb(faces, ruleOptions);
            delete ruleOptions;
            std::vector<NXOpen::SelectionIntentRule*> rules(1, faceRule);
            builder->BoundedObject()->ReplaceRules(rules, false);

            std::vector<NXOpen::NXObject*> selectedOccurrences(1, bFace);
            std::vector<NXOpen::NXObject*> deselectedOccurrences;
            builder->SetSelectedOccurrences(selectedOccurrences, deselectedOccurrences);

            NXOpen::SelectNXObjectList* facetBodies = builder->FacetBodies();
            if (facetBodies != NULL)
            {
                std::vector<NXOpen::NXObject*> facetObjects;
                facetBodies->Add(facetObjects);
            }

            builder->CalculateBoxSize();
            NXOpen::NXObject* object = builder->Commit();
            NXOpen::Features::ToolingBox* toolingBox =
                dynamic_cast<NXOpen::Features::ToolingBox*>(object);
            NXOpen::Features::Feature* feature = toolingBox != NULL ?
                dynamic_cast<NXOpen::Features::Feature*>(toolingBox) :
                dynamic_cast<NXOpen::Features::Feature*>(object);
            boxFeatureTag = feature != NULL ? feature->Tag() :
                (object != NULL ? object->Tag() : NULL_TAG);
            if (toolingBox != NULL)
            {
                std::vector<NXOpen::Body*> bodies = toolingBox->GetBodies();
                if (!bodies.empty() && bodies[0] != NULL)
                {
                    toolBodyTag = bodies[0]->Tag();
                }
            }
            if (toolBodyTag == NULL_TAG)
            {
                toolBodyTag = AskFeatureBodyTag(boxFeatureTag);
            }
            if (toolBodyTag != NULL_TAG)
            {
                UF_OBJ_set_blank_status(toolBodyTag, UF_OBJ_BLANKED);
                toolBodyTags.push_back(toolBodyTag);
                intermediateBodyTags.push_back(toolBodyTag);
            }
            if (boxFeatureTag != NULL_TAG)
            {
                toolFeatureTags.push_back(boxFeatureTag);
            }

            DebugLog("sharp corner tooling box created B-surface=" + TagToString(*bIt) +
                " feature=" + TagToString(boxFeatureTag) +
                " body=" + TagToString(toolBodyTag));
        }
        catch (NXOpen::NXException& ex)
        {
            DebugLogNxException("sharp corner tooling box B-surface=" + TagToString(*bIt), ex);
        }
        catch (...)
        {
            DebugLog("sharp corner tooling box unknown failure B-surface=" + TagToString(*bIt));
        }
        builder->Destroy();
    }

    if (toolBodyTags.empty())
    {
        DebugLog("sharp corner skipped: no tooling bodies created from B-surfaces");
        return finalBodyTag;
    }

    NXOpen::Body* targetBody =
        dynamic_cast<NXOpen::Body*>(NXOpen::NXObjectManager::Get(finalBodyTag));
    if (targetBody == NULL)
    {
        DebugLog("sharp corner skipped: final body object invalid=" + TagToString(finalBodyTag));
        return finalBodyTag;
    }

    std::vector<NXOpen::Body*> toolBodies;
    for (std::size_t index = 0; index < toolBodyTags.size(); ++index)
    {
        NXOpen::Body* toolBody =
            dynamic_cast<NXOpen::Body*>(NXOpen::NXObjectManager::Get(toolBodyTags[index]));
        if (toolBody != NULL && toolBody->Tag() != finalBodyTag)
        {
            toolBodies.push_back(toolBody);
        }
    }
    if (toolBodies.empty())
    {
        DebugLog("sharp corner skipped: no valid tooling body objects");
        return finalBodyTag;
    }

    NXOpen::Features::BooleanBuilder* booleanBuilder = NULL;
    try
    {
        NXOpen::Features::BooleanFeature* nullBooleanFeature = NULL;
        booleanBuilder = workPart->Features()->CreateBooleanBuilderUsingCollector(nullBooleanFeature);
        booleanBuilder->SetTolerance(0.0001);
        booleanBuilder->SetCopyTargets(false);
        booleanBuilder->SetCopyTools(false);
        booleanBuilder->SetOperation(NXOpen::Features::Feature::BooleanTypeSubtract);

        NXOpen::ScCollector* targetCollector = workPart->ScCollectors()->CreateCollector();
        NXOpen::SelectionIntentRuleOptions* targetRuleOptions =
            workPart->ScRuleFactory()->CreateRuleOptions();
        targetRuleOptions->SetSelectedFromInactive(false);
        std::vector<NXOpen::Body*> targetBodies(1, targetBody);
        NXOpen::BodyDumbRule* targetRule =
            workPart->ScRuleFactory()->CreateRuleBodyDumb(targetBodies, true, targetRuleOptions);
        delete targetRuleOptions;
        std::vector<NXOpen::SelectionIntentRule*> targetRules(1, targetRule);
        targetCollector->ReplaceRules(targetRules, false);
        booleanBuilder->SetTargetBodyCollector(targetCollector);

        NXOpen::ScCollector* toolCollector = workPart->ScCollectors()->CreateCollector();
        NXOpen::SelectionIntentRuleOptions* toolRuleOptions =
            workPart->ScRuleFactory()->CreateRuleOptions();
        toolRuleOptions->SetSelectedFromInactive(false);
        NXOpen::BodyDumbRule* toolRule =
            workPart->ScRuleFactory()->CreateRuleBodyDumb(toolBodies, true, toolRuleOptions);
        delete toolRuleOptions;
        std::vector<NXOpen::SelectionIntentRule*> toolRules(1, toolRule);
        toolCollector->ReplaceRules(toolRules, false);
        booleanBuilder->SetToolBodyCollector(toolCollector);

        NXOpen::Features::Feature* feature = booleanBuilder->CommitFeature();
        const tag_t resultBodyTag = AskFirstBodyFromFeature(feature);
        DebugLog("sharp corner subtract committed feature=" +
            TagToString(feature != NULL ? feature->Tag() : NULL_TAG) +
            " resultBody=" + TagToString(resultBodyTag) +
            " toolBodies=" + TagsToString(toolBodyTags) +
            " toolFeatures=" + TagsToString(toolFeatureTags));
        booleanBuilder->Destroy();
        return resultBodyTag != NULL_TAG ? resultBodyTag : finalBodyTag;
    }
    catch (NXOpen::NXException& ex)
    {
        if (booleanBuilder != NULL)
        {
            booleanBuilder->Destroy();
        }
        DebugLogNxException("sharp corner subtract", ex);
        return finalBodyTag;
    }
    catch (...)
    {
        if (booleanBuilder != NULL)
        {
            booleanBuilder->Destroy();
        }
        DebugLog("sharp corner subtract unknown failure");
        return finalBodyTag;
    }
}

void QinLiGuanJian::DeleteIntermediateBodies(
    tag_t originalBodyTag,
    tag_t finalBodyTag,
    const std::vector<tag_t>& bodyTags)
{
    DebugLog("DeleteIntermediateBodies begin original=" + TagToString(originalBodyTag) +
        " final=" + TagToString(finalBodyTag) + " bodies=" + TagsToString(bodyTags));
    if (QinLiGuanJian::theSession == NULL || QinLiGuanJian::theSession->UpdateManager() == NULL)
    {
        DebugLog("DeleteIntermediateBodies skipped: no session/update manager");
        return;
    }

    std::set<tag_t> deleteTagSet;
    if (originalBodyTag != NULL_TAG && originalBodyTag != finalBodyTag)
    {
        deleteTagSet.insert(originalBodyTag);
    }

    for (std::size_t index = 0; index < bodyTags.size(); ++index)
    {
        const tag_t bodyTag = bodyTags[index];
        if (bodyTag != NULL_TAG && bodyTag != finalBodyTag)
        {
            deleteTagSet.insert(bodyTag);
        }
    }

    if (deleteTagSet.empty())
    {
        DebugLog("DeleteIntermediateBodies skipped: empty delete set");
        return;
    }

    std::vector<tag_t> removeParameterBodyTags;
    removeParameterBodyTags.push_back(finalBodyTag);
    for (std::set<tag_t>::const_iterator it = deleteTagSet.begin(); it != deleteTagSet.end(); ++it)
    {
        removeParameterBodyTags.push_back(*it);
    }
    RemoveParametersFromBodies(removeParameterBodyTags);

    std::vector<NXOpen::TaggedObject*> objectsToDelete;
    for (std::set<tag_t>::const_iterator it = deleteTagSet.begin(); it != deleteTagSet.end(); ++it)
    {
        NXOpen::TaggedObject* object = NULL;
        try
        {
            object = NXOpen::NXObjectManager::Get(*it);
        }
        catch (NXOpen::NXException& ex)
        {
            DebugLogNxException("DeleteIntermediateBodies NXObjectManager::Get tag=" + TagToString(*it), ex);
            object = NULL;
        }
        catch (...)
        {
            DebugLog("DeleteIntermediateBodies NXObjectManager::Get unknown exception tag=" + TagToString(*it));
            object = NULL;
        }

        if (object != NULL)
        {
            DebugLog("DeleteIntermediateBodies add delete tag=" + TagToString(*it));
            objectsToDelete.push_back(object);
        }
        else
        {
            DebugLog("DeleteIntermediateBodies skip invalid delete tag=" + TagToString(*it));
        }
    }

    if (objectsToDelete.empty())
    {
        DebugLog("DeleteIntermediateBodies skipped: no valid delete objects");
        return;
    }

    NXOpen::Session::UndoMarkId markId = QinLiGuanJian::theSession->SetUndoMark(
        NXOpen::Session::MarkVisibilityInvisible, "管件斜接处理-删除过程体");
    try
    {
        DebugLog("DeleteIntermediateBodies AddObjectsToDeleteList count=" +
            TagToString(static_cast<tag_t>(objectsToDelete.size())));
        QinLiGuanJian::theSession->UpdateManager()->AddObjectsToDeleteList(objectsToDelete);
        DebugLog("DeleteIntermediateBodies DoUpdate begin");
        QinLiGuanJian::theSession->UpdateManager()->DoUpdate(markId);
        DebugLog("DeleteIntermediateBodies DoUpdate ok");
    }
    catch (NXOpen::NXException& ex)
    {
        DebugLogNxException("DeleteIntermediateBodies DoUpdate", ex);
        throw;
    }
}

std::vector<tag_t> QinLiGuanJian::ExtractEndFacesAsFaceChain(const std::vector<tag_t>& faceTags)
{
    std::vector<tag_t> extractedBodyTags;
    NXOpen::Part* workPart =
        QinLiGuanJian::theSession != NULL && QinLiGuanJian::theSession->Parts() != NULL ?
        QinLiGuanJian::theSession->Parts()->Work() : NULL;
    if (workPart == NULL)
    {
        throw std::runtime_error("未找到工作部件。");
    }

    const std::vector<std::vector<tag_t> > faceGroups = GroupFacesBySharedEdges(faceTags);
    if (faceGroups.empty())
    {
        throw std::runtime_error("未找到可抽取的端面。");
    }

    for (std::size_t groupIndex = 0; groupIndex < faceGroups.size(); ++groupIndex)
    {
        std::vector<NXOpen::Face*> faces;
        std::set<tag_t> uniqueFaceTags;
        for (std::size_t index = 0; index < faceGroups[groupIndex].size(); ++index)
        {
            const tag_t faceTag = faceGroups[groupIndex][index];
            if (faceTag == NULL_TAG || !uniqueFaceTags.insert(faceTag).second)
            {
                continue;
            }

            NXOpen::Face* face = dynamic_cast<NXOpen::Face*>(NXOpen::NXObjectManager::Get(faceTag));
            if (face != NULL)
            {
                faces.push_back(face);
            }
        }

        if (faces.empty())
        {
            continue;
        }

        NXOpen::Features::ExtractFaceBuilder* builder =
            workPart->Features()->CreateExtractFaceBuilder(NULL);
        if (builder == NULL)
        {
            throw std::runtime_error("无法创建抽取几何构建器。");
        }

        try
        {
            builder->SetType(NXOpen::Features::ExtractFaceBuilder::ExtractTypeFace);
            builder->SetFaceOption(NXOpen::Features::ExtractFaceBuilder::FaceOptionTypeFaceChain);
            builder->SetParentPart(NXOpen::Features::ExtractFaceBuilder::ParentPartTypeWorkPart);
            builder->SetAssociative(true);
            builder->SetFixAtCurrentTimestamp(false);
            builder->SetHideOriginal(false);
            builder->SetDeleteHoles(false);
            builder->SetInheritDisplayProperties(false);
            builder->SetInheritMaterial(true);

            NXOpen::SelectionIntentRuleOptions* ruleOptions = workPart->ScRuleFactory()->CreateRuleOptions();
            ruleOptions->SetSelectedFromInactive(false);
            NXOpen::FaceDumbRule* faceRule = workPart->ScRuleFactory()->CreateRuleFaceDumb(faces, ruleOptions);
            delete ruleOptions;
            ruleOptions = NULL;

            std::vector<NXOpen::SelectionIntentRule*> rules(1, faceRule);
            builder->FaceChain()->ReplaceRules(rules, false);

            NXOpen::Features::Feature* feature = builder->CommitFeature();
            const tag_t bodyTag = AskFirstBodyFromFeature(feature);
            if (feature == NULL || bodyTag == NULL_TAG)
            {
                throw std::runtime_error("抽取几何特征创建失败。");
            }
            extractedBodyTags.push_back(bodyTag);
        }
        catch (...)
        {
            builder->Destroy();
            throw;
        }

        builder->Destroy();
    }

    if (extractedBodyTags.empty())
    {
        throw std::runtime_error("未创建任何抽取几何特征。");
    }

    return extractedBodyTags;
}

void QinLiGuanJian::ProcessSelectedFacePreview()
{
    ClearHighlightedFaces();
    if (face_select0 == NULL)
    {
        return;
    }

    NXOpen::BlockStyler::PropertyList* props = NULL;
    try
    {
        props = face_select0->GetProperties();
        std::vector<NXOpen::TaggedObject*> selectedObjects = props->GetTaggedObjectVector("SelectedObjects");
        delete props;
        props = NULL;

        if (selectedObjects.empty() || selectedObjects[0] == NULL)
        {
            return;
        }

        NXOpen::Face* selectedFace = dynamic_cast<NXOpen::Face*>(selectedObjects[0]);
        if (selectedFace == NULL)
        {
            return;
        }

        FaceData selectedData;
        if (!GetFaceData(selectedFace->Tag(), selectedData))
        {
            return;
        }

        DebugLog("preview selected face type=" + TagToString(static_cast<tag_t>(selectedData.type)) +
            " selectedMode=" + TagToString(static_cast<tag_t>(selectedMode)));
    }
    catch (...)
    {
        if (props != NULL)
        {
            delete props;
        }
        throw;
    }
}

